package Learn_Wrapper;

public class Wrapper_03 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		String nums = "300";
		Integer i = Integer.parseInt(nums); // Wrapper conversion from String to Integer
		System.out.println(i);
		int a = Integer.parseInt(nums); // Wrapper conversion from String to int (primitive)
		System.out.println(a);
	}

}
